/**
 * Long-form landing pages written by the client (one Word document each).
 *
 * The JSON files in src/content/landing are generated by
 * scripts/import-landing-pages.py from the client's documents and keep their
 * wording exactly. Don't edit the JSON by hand: change the document and
 * re-run the importer, or the next import will overwrite the edit.
 */
import compressionMolding from "@/content/landing/compression-molding.json";
import customRubberRollers from "@/content/landing/custom-rubber-rollers.json";
import dipMolding from "@/content/landing/dip-molding.json";
import lsrMolding from "@/content/landing/lsr-molding.json";
import refurbishedRubberRollers from "@/content/landing/refurbished-rubber-rollers.json";
import rubberCompounding from "@/content/landing/rubber-compounding.json";
import rubberMolding from "@/content/landing/rubber-molding.json";
import rubberToMetalBonding from "@/content/landing/rubber-to-metal-bonding.json";
import siliconeCompressionMolding from "@/content/landing/silicone-compression-molding.json";
import thermoplasticInjectionMolding from "@/content/landing/thermoplastic-injection-molding.json";
import thermosetMolding from "@/content/landing/thermoset-molding.json";
import transferMolding from "@/content/landing/transfer-molding.json";
import valveAndFlowControl from "@/content/landing/valve-and-flow-control.json";

/** A link or button. `href` "quote" means the RFQ form, pre-filled for the page. */
export type LandingLink = { label: string; href: string };

export type LandingImage = {
  src: string;
  alt: string;
  width: number;
  height: number;
};

export type LandingCard = {
  title: string;
  body: string[];
  /** Set when the card names another landing page */
  href?: string;
  links?: LandingLink[];
};

export type LandingBlock =
  | { type: "p"; text: string; label?: string }
  | { type: "list"; items: { text: string; label?: string }[] }
  | { type: "cards"; items: LandingCard[] }
  | { type: "steps"; items: LandingCard[] }
  | { type: "links"; items: LandingLink[] }
  | { type: "buttons"; items: LandingLink[] }
  | { type: "tagline"; text: string }
  | {
      type: "sub";
      heading: string;
      href?: string;
      image?: LandingImage;
      blocks: LandingBlock[];
    };

export type LandingSection = {
  id: string;
  heading: string;
  lead?: string;
  blocks: LandingBlock[];
};

export type LandingContent = {
  source: string;
  title: string;
  subtitle: string | null;
  tagline: string | null;
  intro: string[];
  cta: LandingLink[];
  /** First intro paragraph that says what SYNC does; used on cards and in search results */
  summary: string;
  sections: LandingSection[];
  faq: { id: string; heading: string; items: { q: string; a: string[] }[] } | null;
  closing: {
    eyebrow: string | null;
    title: string;
    body: string[];
    cta: LandingLink[];
    footnote: string[];
  } | null;
  hero: { src: string; alt: string } | null;
  gallery: LandingImage[];
};

const pages = {
  "compression-molding": compressionMolding,
  "custom-rubber-rollers": customRubberRollers,
  "dip-molding": dipMolding,
  "lsr-molding": lsrMolding,
  "refurbished-rubber-rollers": refurbishedRubberRollers,
  "rubber-compounding": rubberCompounding,
  "rubber-molding": rubberMolding,
  "rubber-to-metal-bonding": rubberToMetalBonding,
  "silicone-compression-molding": siliconeCompressionMolding,
  "thermoplastic-injection-molding": thermoplasticInjectionMolding,
  "thermoset-molding": thermosetMolding,
  "transfer-molding": transferMolding,
  "valve-and-flow-control": valveAndFlowControl,
} as Record<string, LandingContent>;

export type LandingKey = keyof typeof pages;

export function getLanding(key: string): LandingContent | undefined {
  return pages[key];
}
